// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createItem, getSearch, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const collections = "skyramp_search_probe";

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, collections);
    expect(getValue(collectionsPostResponse, "data.collection")).toBe(collections);
    expect(getValue(collectionsPostResponse, "data.meta.collection")).toBe(collections);

    const itemsPostResponse = await createItem(client, URL_localhost, headers, getResponseValue(collectionsPostResponse, "data.meta.collection"), "Quantum Quantum Widget");
    expect(getValue(itemsPostResponse, "data.title")).toBe("Quantum Quantum Widget");
    expect(getValue(itemsPostResponse, "data.id")).toBeGreaterThan(0);

    const itemsPost1Response = await createItem(client, URL_localhost, headers, getResponseValue(collectionsPostResponse, "data.meta.collection"), "A single Quantum item here");
    expect(getValue(itemsPost1Response, "data.title")).toBe("A single Quantum item here");
    expect(getValue(itemsPost1Response, "data.id")).toBeGreaterThan(0);

    const searchGetResponse = await getSearch(client, URL_localhost, headers, "Quantum");
    expect(getValue(searchGetResponse, "errors")).toBeUndefined();
    expect(getValue(searchGetResponse, "total_count")).toBe(2);
    expect(getValue(searchGetResponse, "results").length).toBe(2);
    expect(getValue(searchGetResponse, "total_count")).toBe(getValue(searchGetResponse, "results").length);
    expect(getValue(searchGetResponse, "results.0.collection")).toBe(collections);
    expect(getValue(searchGetResponse, "results.0.id")).toBe(getValue(itemsPostResponse, "data.id"));
    expect(getValue(searchGetResponse, "results.0.field")).toBe("title");
    expect(getValue(searchGetResponse, "results.0.snippet")).toBe("<mark>Quantum</mark> <mark>Quantum</mark> Widget");
    expect(getValue(searchGetResponse, "results.0.score")).toBe(2 / getValue(itemsPostResponse, "data.title").length * 100);
    expect(getValue(searchGetResponse, "results.1.collection")).toBe(collections);
    expect(getValue(searchGetResponse, "results.1.id")).toBe(getValue(itemsPost1Response, "data.id"));
    expect(getValue(searchGetResponse, "results.1.field")).toBe("title");
    expect(getValue(searchGetResponse, "results.1.snippet")).toBe("A single <mark>Quantum</mark> item here");
    expect(getValue(searchGetResponse, "results.1.score")).toBe(1 / getValue(itemsPost1Response, "data.title").length * 100);
    expect(getValue(searchGetResponse, "results.0.score")).toBeGreaterThan(getValue(searchGetResponse, "results.1.score"));
    expect(getValue(searchGetResponse, "results.2")).toBeUndefined();

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, getResponseValue(collectionsPostResponse, "data.collection"));
});
